-- ============================================================================
-- B5 FOLLOW-ON W5 (section 3 pick B, strip): completion. The W1 open-book label
-- comes off the brief of each tier below.
--
-- WHY. W1 (D4 C) labelled these briefs open book because a lesson, a panel's
-- opening view or the page printed some graded answers. Those prints are gone
-- (NextGen zip; src/components/course/panels/completion/capstoneLeak.test.jsx
-- proves each tier prints none and runs a negative control), so the label is
-- no longer true.
--
-- beginner:
--   the string explorer drift table opened on every catalog row and printed both
--   graded casing drifts (7 in 32 lb/ft liner, 13-3/8 in 68 lb/ft surface
--   casing) to seven decimals; it now opens on the tubing class, and placing
--   each casing in its class is the skill the capstone tests
--
-- WHAT MOVES. The brief's first sentence (the label). The brief becomes exactly
-- its text before W1.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after, so no answer grades
-- differently and there is no attempts guard (pick B keeps the keys).
--
-- GUARDS. Each brief must hold its W1-labelled text (md5, rewritten) or its
-- unlabelled text (left alone), with the fields this file was generated
-- against. Anything else raises and the file rolls back. The file refuses
-- unless W1 is applied. Generated by docs/graded-field-audit/w5d_capstones.py.
-- SAFE TO RE-RUN.
--
-- AFTER THIS FILE, 20261024b_w1_openbook_completion.sql reads these tiers as its
-- "published" form again and would put the label back: it is SUPERSEDED and
-- must not be re-applied (/root/w5d-apply/apply.sh reports it so).
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- W1 (20261024*) must be applied: before it, an unlabelled brief is not evidence of anything
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'gasprocessing' and c.tier = 'beginner' and c.active
                    and f->>'key' = 'tegReboilerMMBtuHr') then
    raise exception 'w5d completion refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  -- completion / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'completion' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w5d completion refused: completion/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '5a6de680c3a565de7ca18f10e8073d3e' and fields = '[{"key": "bottom_md_m", "tol": 5E-7, "unit": "m", "label": "String bottom", "expected": 2600.65}, {"key": "packer_bottom_md_m", "tol": 5E-7, "unit": "m", "label": "Packer bottom", "expected": 2594.4}, {"key": "drift_liner_m", "tol": 5E-8, "unit": "m", "label": "Liner drift", "expected": 0.1516126}, {"key": "drift_surface_casing_m", "tol": 1E-7, "unit": "m", "label": "Surface casing drift", "expected": 0.31137224999999996}, {"key": "string_capacity_m3", "tol": 5E-7, "unit": "m3", "label": "String capacity", "expected": 7.852067852872123}, {"key": "string_displacement_m3", "tol": 5E-7, "unit": "m3", "label": "String displacement", "expected": 17.767445424211306}]'::jsonb then 'old'
              when md5(prompt) = 'dc15f59e32c98503cb826fd9178c41bc' and fields = '[{"key": "bottom_md_m", "tol": 5E-7, "unit": "m", "label": "String bottom", "expected": 2600.65}, {"key": "packer_bottom_md_m", "tol": 5E-7, "unit": "m", "label": "Packer bottom", "expected": 2594.4}, {"key": "drift_liner_m", "tol": 5E-8, "unit": "m", "label": "Liner drift", "expected": 0.1516126}, {"key": "drift_surface_casing_m", "tol": 1E-7, "unit": "m", "label": "Surface casing drift", "expected": 0.31137224999999996}, {"key": "string_capacity_m3", "tol": 5E-7, "unit": "m3", "label": "String capacity", "expected": 7.852067852872123}, {"key": "string_displacement_m3", "tol": 5E-7, "unit": "m3", "label": "String displacement", "expected": 17.767445424211306}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'completion' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w5d completion refused: completion/beginner matches neither its W1-labelled form (prompt md5 5a6de680c3a565de7ca18f10e8073d3e) nor its stripped form (prompt md5 dc15f59e32c98503cb826fd9178c41bc), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already stripped
  if v_s0 = 'new' then
    raise notice 'w5d completion: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for a NEW completion. The string is fourteen components of 2-7/8 inch equipment hung at surface, in order from the top: 180 m of tubing; a 0.9 m flow coupling; a 2.2 m safety valve; a 0.9 m flow coupling; 2100 m of tubing; a 6.1 m blast joint; a 2.4 m side pocket mandrel; 300 m of tubing; a 0.4 m X landing nipple; a 1.5 m production packer; 2.5 m of tubing; a 0.45 m XN no-go nipple; a 3.0 m perforated joint; and a 0.3 m wireline entry guide. The 2-7/8 inch tubing has a coupling outside diameter of 3.668 in and a bore of 2.441 in; the safety valve is 5.25 in outside with a 2.313 in bore; the side pocket mandrel is 5.0 in outside at the tubing bore; the packer is 5.875 in outside with a 2.75 in bore; the X nipple bore is 2.313 in and the XN no-go bore is 2.205; the perforated joint is 2.875 in outside at the tubing bore. The well has THREE casing strings: 13-3/8 in surface from 0 to 400 m at a bore of 12.415 in; 9-5/8 in 53.5 lb/ft from 0 to 2200 at 8.535 in; and a 7 in 32 lb/ft liner from 2000 to 2900 at 6.094 in. Total depth is 2900 m. Report: (1) the BOTTOM depth of the string in metres of measured depth; (2) the BOTTOM depth of the PACKER; (3) the API 5CT DRIFT of the 7 in liner in metres; (4) the API 5CT DRIFT of the 13-3/8 in surface casing in metres; (5) the string CAPACITY in cubic metres; and (6) the string DISPLACEMENT in cubic metres. Traps. Field 4 sits at a class boundary: 13-3/8 in is INCLUSIVE in the 5/32 in class and does NOT take the 3/16 in deduction, and getting that wrong costs a thirty second of an inch. The liner is 32 lb/ft and not the lessons 29, so its bore and therefore its drift both differ. Field 2 is the packer BOTTOM and not its top. Fields 5 and 6 are sums over all fourteen components of an area times a length, using the INSIDE diameter for one and the OUTSIDE for the other, and every catalog value here is in inches while every answer is in metres at 0.0254 m to the inch exactly. Free checks: field 1 must equal the sum of the fourteen lengths, because the hanger is at surface; field 6 must exceed field 5, and their difference is the steel; and both drifts must fall short of their nominal bores by one of the four deduction values and by nothing else.'
     where app_slug = 'completion' and tier = 'beginner' and active and md5(prompt) = '5a6de680c3a565de7ca18f10e8073d3e';
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5d completion refused: completion/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'dc15f59e32c98503cb826fd9178c41bc' and fields = '[{"key": "bottom_md_m", "tol": 5E-7, "unit": "m", "label": "String bottom", "expected": 2600.65}, {"key": "packer_bottom_md_m", "tol": 5E-7, "unit": "m", "label": "Packer bottom", "expected": 2594.4}, {"key": "drift_liner_m", "tol": 5E-8, "unit": "m", "label": "Liner drift", "expected": 0.1516126}, {"key": "drift_surface_casing_m", "tol": 1E-7, "unit": "m", "label": "Surface casing drift", "expected": 0.31137224999999996}, {"key": "string_capacity_m3", "tol": 5E-7, "unit": "m3", "label": "String capacity", "expected": 7.852067852872123}, {"key": "string_displacement_m3", "tol": 5E-7, "unit": "m3", "label": "String displacement", "expected": 17.767445424211306}]'::jsonb) from public.academy_capstones where app_slug = 'completion' and tier = 'beginner' and active) is not true then
    raise exception 'w5d completion refused: completion/beginner does not read back as its stripped form';
  end if;

  raise notice 'w5d completion: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
